#[derive(Debug)]
struct FeatureEvaluationRequestEndpoint { provider: Rc<dyn FeatureEvaluationProvider> }

#[derive(Debug)]
pub struct FeatureEvaluationEndpoint<P: FeatureEvaluationProvider> { provider: Rc<P>, request_endpoint: FeatureEvaluationRequestEndpoint }
impl<P: FeatureEvaluationProvider> FeatureEvaluationEndpoint<P> {
    pub fn new(provider: P) -> Self {
        let provider = Rc::new(provider);
        let request_provider: Rc<dyn FeatureEvaluationProvider> = provider.clone();
        Self { provider, request_endpoint: FeatureEvaluationRequestEndpoint { provider: request_provider } }
    }
}

impl<P: FeatureEvaluationProvider> NativeRequestEndpoint for FeatureEvaluationEndpoint<P> {
    fn capability_id(&self) -> &'static str { CAPABILITY_ID }
    fn descriptor_version(&self) -> &'static str { DESCRIPTOR_VERSION }
    fn operations(&self) -> &'static [&'static str] { &[
        EVALUATE_OPERATION,
        EVALUATE_BATCH_OPERATION,
    ] }
    fn typed_endpoint(&self) -> Option<&dyn std::any::Any> { Some(&self.request_endpoint) }
    fn invoke(&self, operation: &str, request: Box<dyn std::any::Any>, context: InvocationContext) -> LocalBoxFuture<'static, Result<Result<Box<dyn std::any::Any>, Box<dyn std::any::Any>>, RuntimeFailure>> {
        match operation {
            EVALUATE_OPERATION => {
                let Ok(request) = request.downcast::<EvaluateRequest>() else {
                    return Box::pin(futures::future::ready(Err(RuntimeFailure::ProtocolViolation { capability: CAPABILITY_ID })));
                };
                let invocation = Rc::clone(&self.provider).evaluate(context, *request);
                Box::pin(async move {
                    invocation.await.map(|result| {
                        result
                            .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                            .map_err(|error| Box::new(error) as Box<dyn std::any::Any>)
                    })
                })
            },
            EVALUATE_BATCH_OPERATION => {
                let Ok(request) = request.downcast::<EvaluateBatchRequest>() else {
                    return Box::pin(futures::future::ready(Err(RuntimeFailure::ProtocolViolation { capability: CAPABILITY_ID })));
                };
                let invocation = Rc::clone(&self.provider).evaluate_batch(context, *request);
                Box::pin(async move {
                    invocation.await.map(|result| {
                        result
                            .map(|value| Box::new(value) as Box<dyn std::any::Any>)
                            .map_err(|error| Box::new(error) as Box<dyn std::any::Any>)
                    })
                })
            }
            _ => Box::pin(futures::future::ready(Err(RuntimeFailure::UnknownOperation { capability: CAPABILITY_ID, operation: operation.to_owned() }))),
        }
    }
}

