#[derive(Debug)]
pub struct FeatureEvaluationClient {
    evaluate: NativeRequestHandle<FeatureEvaluationEvaluate>,
    evaluate_batch: NativeRequestHandle<FeatureEvaluationEvaluateBatch>,
}
impl FeatureEvaluationClient {
    pub fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        <Self as CapabilityClient>::from_dependencies(dependencies)
    }

    pub async fn evaluate(&self, request: EvaluateRequest) -> Result<EvaluateResponse, FeatureEvaluationEvaluateInvocationError> {
        self.evaluate.invoke(EVALUATE_OPERATION, request).await
            .map_err(FeatureEvaluationEvaluateInvocationError::Runtime)?
            .map_err(FeatureEvaluationEvaluateInvocationError::Domain)
    }

    pub async fn evaluate_with_context(&self, context: InvocationContext, request: EvaluateRequest) -> Result<EvaluateResponse, FeatureEvaluationEvaluateInvocationError> {
        self.evaluate.invoke_with_context(EVALUATE_OPERATION, context, request).await
            .map_err(FeatureEvaluationEvaluateInvocationError::Runtime)?
            .map_err(FeatureEvaluationEvaluateInvocationError::Domain)
    }

    pub async fn evaluate_batch(&self, request: EvaluateBatchRequest) -> Result<EvaluateBatchResponse, FeatureEvaluationEvaluateBatchInvocationError> {
        self.evaluate_batch.invoke(EVALUATE_BATCH_OPERATION, request).await
            .map_err(FeatureEvaluationEvaluateBatchInvocationError::Runtime)?
            .map_err(FeatureEvaluationEvaluateBatchInvocationError::Domain)
    }

    pub async fn evaluate_batch_with_context(&self, context: InvocationContext, request: EvaluateBatchRequest) -> Result<EvaluateBatchResponse, FeatureEvaluationEvaluateBatchInvocationError> {
        self.evaluate_batch.invoke_with_context(EVALUATE_BATCH_OPERATION, context, request).await
            .map_err(FeatureEvaluationEvaluateBatchInvocationError::Runtime)?
            .map_err(FeatureEvaluationEvaluateBatchInvocationError::Domain)
    }
}

impl CapabilityClient for FeatureEvaluationClient {
    type Dependencies = PluginDependencies;
    type Error = RuntimeFailure;

    const CAPABILITY_ID: &'static str = CAPABILITY_ID;
    const DESCRIPTOR_VERSION: &'static str = DESCRIPTOR_VERSION;

    fn from_dependencies(dependencies: &PluginDependencies) -> Result<Self, RuntimeFailure> {
        Ok(Self {
            evaluate: dependencies.one::<FeatureEvaluationEvaluate>()?,
            evaluate_batch: dependencies.one::<FeatureEvaluationEvaluateBatch>()?,
        })
    }

    fn already_connected() -> RuntimeFailure {
        RuntimeFailure::PluginFailure {
            detail: format!("Capability Port {CAPABILITY_ID} was connected more than once"),
        }
    }
}

impl CapabilityClientMany for FeatureEvaluationClient {
    fn many_from_dependencies(
        dependencies: &PluginDependencies,
    ) -> Result<Vec<BoundCapabilityClient<Self>>, RuntimeFailure> {
        dependencies
            .bindings()
            .iter()
            .filter(|binding| binding.capability_id() == CAPABILITY_ID)
            .map(|binding| {
                Ok(BoundCapabilityClient::new(
                    binding.provider_instance(),
                    Self {
                    evaluate: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<FeatureEvaluationEvaluate>()?,
                    evaluate_batch: binding.handle().ok_or(RuntimeFailure::Unavailable { capability: CAPABILITY_ID })?.typed::<FeatureEvaluationEvaluateBatch>()?,
                    },
                ))
            })
            .collect()
    }
}

